(function(){angular.module("app.core").directive("msSidenavHelper",msSidenavHelperDirective);function msSidenavHelperDirective(){return{restrict:"A",require:"^mdSidenav",link:function(scope,iElement,iAttrs,MdSidenavCtrl){scope.$watch(function(){return MdSidenavCtrl.isOpen()&&!MdSidenavCtrl.isLockedOpen()
},function(current){if(angular.isUndefined(current)){return}iElement.parent().toggleClass("full-height",current);angular.element("html").toggleClass("sidenav-open",current)})}}}})();